cat > src/main.rs <<'EOF'
//! Report account balances from a ledger file.

use std::collections::HashMap;
use std::env;
use std::fs;

/// Parse a non-negative decimal amount such as `12.05` into cents.
fn to_cents(amount: &str) -> i128 {
    let (whole, frac) = amount.split_once('.').unwrap_or((amount, ""));
    let whole: i128 = whole.parse().unwrap_or(0);
    let mut frac_cents: i128 = frac.parse().unwrap_or(0);
    if frac.len() == 1 {
        frac_cents *= 10;
    }
    whole * 100 + frac_cents
}

fn format_cents(cents: i128) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

fn main() {
    let path = env::args().nth(1).expect("a ledger path");
    let text = fs::read_to_string(&path).expect("a readable ledger");
    let mut lines = text.lines();
    let n: usize = lines
        .next()
        .and_then(|h| h.split_whitespace().nth(1))
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);

    let mut balances: HashMap<String, i128> = HashMap::new();
    for k in 1..=n {
        let line = lines.next().unwrap_or("").trim();
        let mut parts = line.rsplitn(3, char::is_whitespace);
        let amount = parts.next().unwrap_or("");
        let kind = parts.next().unwrap_or("");
        let account = parts.next().unwrap_or("").trim_end();
        let cents = to_cents(amount);
        let signed = match kind {
            "credit" => cents,
            "debit" => -cents,
            _ => {
                println!("ERROR line {}", k);
                return;
            }
        };
        *balances.entry(account.to_string()).or_insert(0) += signed;
    }

    let mut entries: Vec<(String, i128)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.as_bytes().cmp(b.0.as_bytes())));
    let mut total: i128 = 0;
    for (account, balance) in &entries {
        println!("{} {}", account, format_cents(*balance));
        total += balance;
    }
    println!("TOTAL {}", format_cents(total));
}
EOF
